function main(): void {
var j;
var i;
var str;
var res;

var whitespaceChars = [
  0x0009,
  0x000A,
  0x000B,
  0x000C,
  0x000D,
  0x0020,
  0x00A0,
  0x1680,
  0x2000,
  0x2001,
  0x2002,
  0x2003,
  0x2004,
  0x2005,
  0x2006,
  0x2007,
  0x2008,
  0x2009,
  0x200A,
  0x2028,
  0x2029,
  0x202F,
  0x205F,
  0x3000,
];

for (j = 0x0000; j < 0x10000; j++) {
  if (j === 0x180E) { continue; } // Skip 0x180E, current test in a separate file
  if (j === 0xFEFF) { continue; } // Ignore BOM
  str = String.fromCharCode(j);
  res = str.replace(/\S+/g, "test262");
  if (whitespaceChars.indexOf(j) >= 0) {
    assert.sameValue(res, str, "WhiteSpace character, charCode: " + j);
  } else {
    assert.sameValue(res, "test262", "Non WhiteSpace character, charCode: " + j);
  }
}
}
main();

function main(): void {
const str = buildString(
{
  loneCodePoints: [],
  ranges: [
    [0x00DC00, 0x00DFFF],
    [0x000000, 0x00002F],
    [0x00003A, 0x00DBFF],
    [0x00E000, 0x10FFFF]
  ]
}
);

const standard = /\d/;
const unicode = /\d/u;
const vflag = /\d/v;
const regexes = [standard,unicode,vflag];

const errors = [];

for (const regex of regexes) {
  if (regex.test(str)) {
    // Error, let's find out where
    for (const char of str) {
      if (regex.test(char)) {
        errors.push('0x' + char.codePointAt(0).toString(16));
      }
    }
  }
}

assert.sameValue(
  errors.length,
  0,
  'Expected no match, but matched: ' + errors.join(',')
);
}
main();

