function main(): void {
// Positive lookahead with quantifier.
assert.throws(SyntaxError, function() {
  RegExp("(?=.)*", "u");
}, 'RegExp("(?=.)*", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.)+", "u");
}, 'RegExp("(?=.)+", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.)?", "u");
}, 'RegExp("(?=.)?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.){1}", "u");
}, 'RegExp("(?=.){1}", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.){1,}", "u");
}, 'RegExp("(?=.){1,}", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.){1,2}", "u");
}, 'RegExp("(?=.){1,2}", "u"): ');


// Positive lookahead with reluctant quantifier.
assert.throws(SyntaxError, function() {
  RegExp("(?=.)*?", "u");
}, 'RegExp("(?=.)*?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.)+?", "u");
}, 'RegExp("(?=.)+?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.)??", "u");
}, 'RegExp("(?=.)??", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.){1}?", "u");
}, 'RegExp("(?=.){1}?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.){1,}?", "u");
}, 'RegExp("(?=.){1,}?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?=.){1,2}?", "u");
}, 'RegExp("(?=.){1,2}?", "u"): ');


// Negative lookahead with quantifier.
assert.throws(SyntaxError, function() {
  RegExp("(?!.)*", "u");
}, 'RegExp("(?!.)*", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.)+", "u");
}, 'RegExp("(?!.)+", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.)?", "u");
}, 'RegExp("(?!.)?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.){1}", "u");
}, 'RegExp("(?!.){1}", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.){1,}", "u");
}, 'RegExp("(?!.){1,}", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.){1,2}", "u");
}, 'RegExp("(?!.){1,2}", "u"): ');


// Negative lookahead with reluctant quantifier.
assert.throws(SyntaxError, function() {
  RegExp("(?!.)*?", "u");
}, 'RegExp("(?!.)*?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.)+?", "u");
}, 'RegExp("(?!.)+?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.)??", "u");
}, 'RegExp("(?!.)??", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.){1}?", "u");
}, 'RegExp("(?!.){1}?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.){1,}?", "u");
}, 'RegExp("(?!.){1,}?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("(?!.){1,2}?", "u");
}, 'RegExp("(?!.){1,2}?", "u"): ');
}
main();

function main(): void {
// Quantifier without atom.
assert.throws(SyntaxError, function() {
  RegExp("*", "u");
}, 'RegExp("*", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("+", "u");
}, 'RegExp("+", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("?", "u");
}, 'RegExp("?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("{1}", "u");
}, 'RegExp("{1}", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("{1,}", "u");
}, 'RegExp("{1,}", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("{1,2}", "u");
}, 'RegExp("{1,2}", "u"): ');


// Reluctant quantifier without atom.
assert.throws(SyntaxError, function() {
  RegExp("*?", "u");
}, 'RegExp("*?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("+?", "u");
}, 'RegExp("+?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("??", "u");
}, 'RegExp("??", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("{1}?", "u");
}, 'RegExp("{1}?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("{1,}?", "u");
}, 'RegExp("{1,}?", "u"): ');
assert.throws(SyntaxError, function() {
  RegExp("{1,2}?", "u");
}, 'RegExp("{1,2}?", "u"): ');
}
main();
